func (this *Exchange) fetchRestOrderBookSafeBody(ch chan any, symbol any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	chSent := false
	_ = chSent
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 0, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	var fetchSnapshotMaxRetries any = this.HandleOption("watchOrderBook", "maxRetries", 3)
	for i := 0; IsLessThan(i, fetchSnapshotMaxRetries); i++ {

		{
			func(this *Exchange) (ret_ any) {
				defer func() {
					if e := recover(); e != nil {
						if e == "break" {
							return
						}
						ret_ = func(this *Exchange) any {
							// catch block:
							if IsEqual((i + 1), fetchSnapshotMaxRetries) {
								panic(e)
							}
							return nil
						}(this)
					}
				}()
				// try block:

				orderBook := <-this.DerivedExchange.FetchOrderBookAsync(StringArg(symbol), limit, params)
				PanicOnError(orderBook)

				ch <- orderBook
				chSent = true
				return nil

			}(this)
			if chSent {
				return nil
			}

		}
	}

	return nil
}
